# hypothesis: A frozen dataclass Final field declared as int | str keeps the union type on instances, and reassigning it through an instance is rejected by both checkers.
from dataclasses import dataclass
from typing import ClassVar, Final, reveal_type


@dataclass(frozen=True)
class Config:
    name: Final[str]
    limit: Final[int | str] = 3
    registry: ClassVar[dict[str, int]] = {}

    def describe(self) -> str:
        return f'{self.name}={self.limit}'


def try_reassign(c: Config) -> str:
    c.limit = 'many'  # expect-error
    return c.describe()


def count_registry() -> int:
    Config.registry['hits'] = Config.registry.get('hits', 0) + 1
    return Config.registry['hits']


cfg = Config('alpha', 7)
cfg2 = Config('beta', 'lots')
reveal_type(cfg.limit)
reveal_type(cfg2.limit)
reveal_type(Config.registry)
print(cfg.describe(), cfg2.describe())
print(count_registry(), count_registry())
try:
    print(try_reassign(cfg))
except Exception as exc:
    print(type(exc).__name__)
